CREATE TABLE git_change_sets (id UUID PRIMARY KEY,pipeline_run_id UUID NOT NULL REFERENCES pipeline_runs(id) ON DELETE CASCADE,base_sha VARCHAR(128) NOT NULL,head_sha VARCHAR(128) NOT NULL,total_changed_files INTEGER NOT NULL,provider VARCHAR(32) NOT NULL,ingested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_change_set UNIQUE(pipeline_run_id,base_sha,head_sha));
CREATE TABLE changed_files (id UUID PRIMARY KEY,change_set_id UUID NOT NULL REFERENCES git_change_sets(id) ON DELETE CASCADE,path TEXT NOT NULL,previous_path TEXT,change_type VARCHAR(32) NOT NULL,file_category VARCHAR(64) NOT NULL,module_hint VARCHAR(255),additions INTEGER,deletions INTEGER,changes INTEGER);
CREATE TABLE change_relevance_results (id UUID PRIMARY KEY,pipeline_run_id UUID NOT NULL REFERENCES pipeline_runs(id) ON DELETE CASCADE,failure_event_id UUID NOT NULL REFERENCES failure_events(id) ON DELETE CASCADE,fingerprint VARCHAR(64) NOT NULL,relevance VARCHAR(32) NOT NULL,confidence DOUBLE PRECISION NOT NULL,analyzer_version VARCHAR(64) NOT NULL,summary TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_relevance UNIQUE(failure_event_id,analyzer_version));
CREATE INDEX idx_changed_files_category ON changed_files(file_category); CREATE INDEX idx_relevance_run ON change_relevance_results(pipeline_run_id);
